$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
$schemaPath=Join-Path $root 'review\contracts\hirc-cultural-participation.candidate.schema.json';$fixturePath=Join-Path $root 'review\fixtures\cultural-participation-contract-cases-v1.json';$resultPath=Join-Path $root 'review\fixtures\cultural-participation-contract-validation-v1.json'
$fixtures=Get-Content $fixturePath -Raw -Encoding UTF8|ConvertFrom-Json -Depth 100
function Copy-O($v){return(ConvertFrom-Json -InputObject(ConvertTo-Json -InputObject $v -Depth 100 -Compress)-Depth 100)}
function Set-P($o,$p){$parts=$p.path.Split('.');$c=$o;for($i=0;$i-lt$parts.Count-1;$i++){$c=$c.($parts[$i])};$raw=$p.PSObject.Properties['value'].Value;$v=ConvertFrom-Json -InputObject(ConvertTo-Json -InputObject $raw -Depth 100 -Compress)-Depth 100 -NoEnumerate;$c|Add-Member -NotePropertyName $parts[-1] -NotePropertyValue $v -Force}
function Test-S($p){$e=[Collections.Generic.List[string]]::new();$allowed=@{'ABSENT'=@('INVITED');'INVITED'=@('JOINED','LEFT');'JOINED'=@('SUBSCRIBED','QUIET','DISSENTING','LEFT');'SUBSCRIBED'=@('QUIET','DISSENTING','LEFT');'QUIET'=@('SUBSCRIBED','DISSENTING','LEFT');'DISSENTING'=@('SUBSCRIBED','QUIET','LEFT');'LEFT'=@();'HELD'=@('LEFT')};$last=$null;foreach($x in @($p.events)){if($null-ne$last-and$x.from-ne$last){$e.Add('event-chain')};if($x.to-notin$allowed[$x.from]){$e.Add('invalid-transition')};$last=$x.to};if($last-ne$p.state){$e.Add('terminal-state-mismatch')};$currentAccept=($p.consent.state-eq'EXPLICIT_ACCEPT'-and$p.consent.current-eq$true);if($p.subscription.active-eq$true-and-not$currentAccept){$e.Add('active-subscription-without-current-consent')};if($p.state-in@('JOINED','SUBSCRIBED','QUIET')-and-not$currentAccept){$e.Add('active-state-without-current-consent')};if($p.state-eq'LEFT'-and($p.subscription.active-ne$false-or$p.consent.state-ne'WITHDRAWN')){$e.Add('exit-state-incomplete')};return @($e|Sort-Object -Unique)}
$rows=@();foreach($case in $fixtures.cases){$p=Copy-O $fixtures.base;foreach($patch in @($case.patches)){Set-P $p $patch};$json=$p|ConvertTo-Json -Depth 100;$se=@();$ok=Test-Json -Json $json -SchemaFile $schemaPath -ErrorAction SilentlyContinue -ErrorVariable se;$me=if($ok){@(Test-S $p)}else{@()};$ss=if($ok){'ACCEPT'}else{'REJECT'};$ms=if(-not$ok){'NOT_RUN'}elseif($me.Count-eq0){'ACCEPT'}else{'REJECT'};$rows+=[ordered]@{name=$case.name;expected_structural=$case.expected_structural;actual_structural=$ss;expected_semantic=$case.expected_semantic;actual_semantic=$ms;semantic_errors=@($me);pass=($ss-eq$case.expected_structural-and$ms-eq$case.expected_semantic)}}
$result=[ordered]@{schema='hirc.cultural-participation-validation/1';stone='M03-S009';schema_binding=[ordered]@{path='review/contracts/hirc-cultural-participation.candidate.schema.json';sha256=(Get-FileHash $schemaPath -Algorithm SHA256).Hash.ToLower()};fixture_binding=[ordered]@{path='review/fixtures/cultural-participation-contract-cases-v1.json';sha256=(Get-FileHash $fixturePath -Algorithm SHA256).Hash.ToLower()};harness_binding=[ordered]@{path='review/fixtures/validate_cultural_participation_contract.ps1';sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLower()};runtime=[ordered]@{powershell=$PSVersionTable.PSVersion.ToString();test_json_module=(Get-Command Test-Json).Version.ToString()};cases=$rows;all_cases_pass=@($rows|Where-Object { $_.pass -eq $false }).Count -eq 0;protected_real_bodies_used=$false;claim='Synthetic structural and transition behavior only; not real consent, voluntariness, accessibility, non-retaliation, standing, permission or runtime evidence.'}
$resultJson=($result|ConvertTo-Json -Depth 100)-replace "`r`n","`n";[IO.File]::WriteAllText($resultPath,$resultJson+"`n",[Text.UTF8Encoding]::new($false));$resultJson;if(-not$result.all_cases_pass){exit 1}
